  let g = b.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#07040f'); g.addColorStop(.55, '#140616'); g.addColorStop(1, '#22061a');
  b.fillStyle = g; b.fillRect(0, 0, W, H);
