/* ---------- text helpers ---------- */
function fontFor(f, size) { return (f === 'Great Vibes' ? '400 ' : (f === 'Playfair Display' ? 'italic 700 ' : '700 ')) + size + 'px "' + f + '", "Noto Serif", "Noto Color Emoji", serif'; }
