  const short = h.text.replace(/\n/g, '').length <= 5;
  const max = Math.min(W * (h.f === 'Great Vibes' ? .27 : short ? .25 : .2), h.f === 'Great Vibes' ? 132 : short ? 124 : 104);
  let size = max;
