  if (h.tr) { ctx.font = 'italic 400 21px Poppins, sans-serif'; ctx.fillStyle = 'rgba(255,235,242,.85)'; ctx.shadowBlur = 0; ctx.fillText('“' + h.tr + '”', W / 2, ly + 34); }
