/* ---------- soft piano (WebAudio) ---------- */
const Music = (() => {
  let ac = null, master = null, on = false, timer = null, step = 0, nextT = 0, verb = null;
  const prog = [[57, 60, 64, 69], [53, 57, 60, 65], [48, 52, 55, 60], [55, 59, 62, 67]]; // Am F C G
  const mel = [76, 74, 72, 74, 76, 79, 76, 74, 72, 71, 72, 74, 72, 69, 67, 69];
  const f = m => 440 * Math.pow(2, (m - 69) / 12);
  function note(m, t, v, d) {
    const o1 = ac.createOscillator(), o2 = ac.createOscillator(), g = ac.createGain();
    o1.type = 'sine'; o2.type = 'triangle'; o1.frequency.value = f(m); o2.frequency.value = f(m) * 2; o2.detune.value = 3;
    const g2 = ac.createGain(); g2.gain.value = .18;
    o1.connect(g); o2.connect(g2); g2.connect(g); g.connect(master); g.connect(verb);
    g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + .012); g.gain.exponentialRampToValueAtTime(.0008, t + d);
    o1.start(t); o2.start(t); o1.stop(t + d + .05); o2.stop(t + d + .05);
  }
  function sched() {
    while (nextT < ac.currentTime + .4) {
      const bar = Math.floor(step / 8) % 4, b = step % 8, ch = prog[bar];
      if (b === 0) note(ch[0] - 12, nextT, .16, 3.2);
      note(ch[[1, 2, 3, 2, 1, 2, 3, 2][b]], nextT, .07, 1.6);
      if (b % 2 === 0) note(mel[(Math.floor(step / 2)) % mel.length], nextT, .09, 2.2);
      nextT += .38; step++;
    }
  }
  function start() {
    try {
      if (!ac) {
        ac = new (window.AudioContext || window.webkitAudioContext)(); master = ac.createGain(); master.gain.value = .0; master.connect(ac.destination);
        verb = ac.createConvolver(); const len = ac.sampleRate * 2.6, ir = ac.createBuffer(2, len, ac.sampleRate);
        for (let c = 0; c < 2; c++) { const d = ir.getChannelData(c); for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2.6); }
        verb.buffer = ir; const vg = ac.createGain(); vg.gain.value = .35; verb.connect(vg); vg.connect(master);
      }
      ac.resume(); nextT = ac.currentTime + .1; on = true;
      master.gain.cancelScheduledValues(ac.currentTime); master.gain.setTargetAtTime(.8, ac.currentTime, .6);
      clearInterval(timer); timer = setInterval(sched, 120); mbtn.textContent = '🎵'; mbtn.setAttribute('aria-label', 'Music on');
    } catch (e) { }
  }
  function stop() { if (!ac) return; on = false; master.gain.setTargetAtTime(0, ac.currentTime, .2); setTimeout(() => clearInterval(timer), 600); mbtn.textContent = '🔇'; mbtn.setAttribute('aria-label', 'Music off'); }
  return { start, stop, toggle() { on ? stop() : start(); } };
})();
mbtn.addEventListener('click', () => Music.toggle());

/* ---------- boot ---------- */
async function fontsReady() {
  const fams = new Map();
  for (const h of HEAD.concat(CLOUD)) fams.set(h.f, (fams.get(h.f) || '') + h.text);
  const jobs = [];
  for (const [f, txt] of fams) jobs.push(document.fonts.load(fontFor(f, 40).replace(', "Noto Serif", "Noto Color Emoji", serif', ''), txt.replace(/\n/g, '')));
  jobs.push(document.fonts.load('italic 700 40px "Noto Serif"', "Σ' αγαπώ ʻ"), document.fonts.load('700 40px "Noto Serif"', "Σ' αγαπώ ʻ"));
  jobs.push(document.fonts.load('400 40px "Great Vibes"', NAME + 'one meaning'), document.fonts.load('800 26px Poppins'), document.fonts.load('600 22px Poppins'), document.fonts.load('italic 400 21px Poppins'));
  await Promise.race([Promise.allSettled(jobs), new Promise(r => setTimeout(r, 6000))]);
}
let lastW = 0, lastH = 0;
window.addEventListener('resize', () => { if (Math.abs(window.innerWidth - lastW) > 2 || Math.abs(window.innerHeight - lastH) > 60) { lastW = window.innerWidth; lastH = window.innerHeight; layout(); if (started) { const t = now() - T0; buildSegs(); segDone = 0; } } });
(async function boot() {
  $('#who').textContent = NAME;
  await fontsReady();
  lastW = window.innerWidth; lastH = window.innerHeight;
  layout(); buildSegs();
  requestAnimationFrame(frame);
  window.__api = { phase: () => started ? (window.__t < S0 ? 'head' : window.__t < S1 ? 'storm' : window.__t < G0 ? 'meaning' : window.__t < R0 ? 'heart' : window.__t < PN ? 'rose' : 'final') : 'intro', T: { H0, S0, S1, G0, HB, R0, FL, PN, DONE } };
  window.__ready = true;
  if (DEMO) setTimeout(() => { btn.classList.add('tap'); setTimeout(begin, 350); }, 2000);
})();
